insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('platform-public-media','platform-public-media',true,8388608,array['image/png','image/jpeg','image/webp']) on conflict (id) do update set public=true,file_size_limit=8388608,allowed_mime_types=array['image/png','image/jpeg','image/webp'];
drop policy if exists platform_public_media_owner_insert on storage.objects;
create policy platform_public_media_owner_insert on storage.objects for insert to authenticated with check (bucket_id='platform-public-media' and (storage.foldername(name))[1]=auth.uid()::text and exists(select 1 from public.platform_memberships pm where pm.user_id=auth.uid() and pm.status='active'));
drop policy if exists platform_public_media_owner_update on storage.objects;
create policy platform_public_media_owner_update on storage.objects for update to authenticated using (bucket_id='platform-public-media' and (storage.foldername(name))[1]=auth.uid()::text and exists(select 1 from public.platform_memberships pm where pm.user_id=auth.uid() and pm.status='active')) with check (bucket_id='platform-public-media' and (storage.foldername(name))[1]=auth.uid()::text and exists(select 1 from public.platform_memberships pm where pm.user_id=auth.uid() and pm.status='active'));
drop policy if exists platform_public_media_owner_delete on storage.objects;
create policy platform_public_media_owner_delete on storage.objects for delete to authenticated using (bucket_id='platform-public-media' and (storage.foldername(name))[1]=auth.uid()::text and exists(select 1 from public.platform_memberships pm where pm.user_id=auth.uid() and pm.status='active'));